function symulujWatek(liczbaWiadomosci) {
  let liczbaNieprzeczytanych = liczbaWiadomosci;

  function przeczytajJedna() {
    if (liczbaNieprzeczytanych > 0) {
      liczbaNieprzeczytanych = liczbaNieprzeczytanych - 1;
    }
  }

  przeczytajJedna();
  przeczytajJedna();

  return liczbaNieprzeczytanych;
}

console.log(symulujWatek(5)); // 3

